"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Icon } from "../icons/icon";

export interface AuthLayoutProps extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * "split" zet een gekleurd paneel naast het formulier (verdwijnt op mobiel),
   * "centered" zet de kaart midden op een zachte achtergrond.
   */
  variant?: "split" | "centered";
  /** Inhoud van het zijpaneel bij `split`. */
  aside?: React.ReactNode;
  /** Donker paneel in plaats van het accentverloop. */
  asideTone?: "accent" | "ink";
  /** Zijpaneel links of rechts. */
  asidePosition?: "left" | "right";
}

/**
 * AuthLayout — het frame rond een aanmeldscherm. Split zet een merkpaneel naast
 * het formulier, centered zet de kaart midden op het scherm met een zachte gloed.
 */
export const AuthLayout = React.forwardRef<HTMLDivElement, AuthLayoutProps>(function AuthLayout(
  { variant = "split", aside, asideTone = "accent", asidePosition = "left", className, children, ...rest },
  ref
) {
  return (
    <div
      ref={ref}
      className={cn("pxui-auth", `pxui-auth-${variant}`, `pxui-auth-aside-${asidePosition}`, className)}
      {...rest}
    >
      {variant === "split" && aside && (
        <aside className={cn("pxui-auth-aside", `pxui-auth-aside-${asideTone}`)}>
          <span className="pxui-auth-deco" aria-hidden="true" />
          <span className="pxui-auth-grid" aria-hidden="true" />
          <div className="pxui-auth-aside-inner">{aside}</div>
        </aside>
      )}

      <main className="pxui-auth-main">
        {variant === "centered" && (
          <>
            <span className="pxui-auth-glow" aria-hidden="true" />
            <span className="pxui-auth-glow pxui-auth-glow-two" aria-hidden="true" />
          </>
        )}
        {children}
      </main>
    </div>
  );
});

export interface AuthCardProps extends Omit<React.HTMLAttributes<HTMLElement>, "title"> {
  /** Merknaam en logo bovenaan. */
  brand?: React.ReactNode;
  title: React.ReactNode;
  description?: React.ReactNode;
  /** Inhoud onder de kaart, bv. "Nog geen account?". */
  footer?: React.ReactNode;
  /** Rendert een <form> in plaats van een <div>. */
  as?: "div" | "form";
}

/** AuthCard — de kaart met titel, formulier en voettekst. */
export const AuthCard = React.forwardRef<HTMLElement, AuthCardProps>(function AuthCard(
  { brand, title, description, footer, as = "form", className, children, ...rest },
  ref
) {
  const Comp = as as React.ElementType;

  return (
    <Comp ref={ref} className={cn("pxui-auth-card", className)} {...rest}>
      {brand && <div className="pxui-auth-brand">{brand}</div>}
      <h1 className="pxui-auth-title">{title}</h1>
      {description && <p className="pxui-auth-description">{description}</p>}
      <div className="pxui-auth-body">{children}</div>
      {footer && <div className="pxui-auth-footer">{footer}</div>}
    </Comp>
  );
});

export interface AuthDividerProps extends React.HTMLAttributes<HTMLDivElement> {
  children?: React.ReactNode;
}

/** AuthDivider — "of met e-mail"-scheiding tussen SSO en formulier. */
export const AuthDivider = React.forwardRef<HTMLDivElement, AuthDividerProps>(function AuthDivider(
  { className, children = "of", ...rest },
  ref
) {
  return (
    <div ref={ref} className={cn("pxui-auth-divider", className)} {...rest}>
      <span>{children}</span>
    </div>
  );
});

export interface SsoButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  /** Logo of icoon links. */
  icon?: React.ReactNode;
  label: React.ReactNode;
  /** Kleine regel onder het label. */
  description?: React.ReactNode;
  /** Toont een spinner en blokkeert de knop. */
  loading?: boolean;
  loadingLabel?: React.ReactNode;
  /** Merkkleur van de aanbieder, bv. de itsme®-oranje. */
  color?: string;
}

/** SsoButton — brede knop voor eID, itsme® of een andere aanbieder. */
export const SsoButton = React.forwardRef<HTMLButtonElement, SsoButtonProps>(function SsoButton(
  { icon, label, description, loading, loadingLabel = "Aanmelden…", color, className, style, disabled, ...rest },
  ref
) {
  return (
    <button
      ref={ref}
      type="button"
      disabled={disabled || loading}
      data-loading={loading ? "" : undefined}
      className={cn("pxui-sso", className)}
      style={color ? ({ ["--pxui-sso-color" as string]: color, ...style } as React.CSSProperties) : style}
      {...rest}
    >
      <span className="pxui-sso-icon">
        {loading ? <Icon name="loader" size={18} className="pxui-sso-spin" /> : icon}
      </span>
      <span className="pxui-sso-text">
        <span className="pxui-sso-label">{loading ? loadingLabel : label}</span>
        {description && !loading && <span className="pxui-sso-description">{description}</span>}
      </span>
      {!loading && <Icon name="chevronRight" size={17} className="pxui-sso-arrow" />}
    </button>
  );
});

/* ============================ AuthLayout ============================ */
.pxui-auth { min-height: 100vh; background: var(--bg); }

.pxui-auth-split { display: grid; grid-template-columns: 1fr 1fr; }
.pxui-auth-split.pxui-auth-aside-right { direction: rtl; }
.pxui-auth-split.pxui-auth-aside-right > * { direction: ltr; }

.pxui-auth-centered { display: grid; place-items: center; background: var(--bg-grad); }

/* ---------- Zijpaneel ---------- */
.pxui-auth-aside {
  position: relative; overflow: hidden;
  padding: 48px;
  display: flex; flex-direction: column; justify-content: space-between;
  color: var(--text-inv);
  background: linear-gradient(150deg, var(--accent-hover) 0%, var(--accent) 45%, var(--accent-active) 100%);
}
.pxui-auth-aside-ink {
  background: linear-gradient(
    150deg,
    color-mix(in srgb, var(--accent-active) 26%, var(--text)) 0%,
    var(--text) 60%,
    color-mix(in srgb, var(--text) 82%, #000) 100%
  );
}
.pxui-auth-aside-inner { position: relative; z-index: 1; display: flex; flex-direction: column; gap: 20px; height: 100%; justify-content: space-between; }

.pxui-auth-deco {
  position: absolute; inset: 0; opacity: .5;
  background-image:
    radial-gradient(circle at 80% 10%, rgba(255, 255, 255, .18), transparent 40%),
    radial-gradient(circle at 10% 90%, rgba(255, 255, 255, .10), transparent 35%);
}
.pxui-auth-grid {
  position: absolute; inset: 0; opacity: .12;
  background-image:
    linear-gradient(rgba(255, 255, 255, .6) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, .6) 1px, transparent 1px);
  background-size: 40px 40px;
  -webkit-mask-image: radial-gradient(circle at 70% 30%, black, transparent 70%);
  mask-image: radial-gradient(circle at 70% 30%, black, transparent 70%);
}

/* ---------- Formulierkant ---------- */
.pxui-auth-main {
  position: relative; display: flex; align-items: center; justify-content: center;
  padding: 40px 24px; min-width: 0;
}
.pxui-auth-glow {
  position: absolute; width: 460px; height: 460px; border-radius: var(--r-full);
  background: radial-gradient(circle, color-mix(in srgb, var(--accent) 22%, transparent), transparent 70%);
  top: -120px; left: -80px; pointer-events: none; filter: blur(20px);
}
.pxui-auth-glow-two {
  top: auto; left: auto; right: -110px; bottom: -140px;
  background: radial-gradient(circle, color-mix(in srgb, var(--violet) 18%, transparent), transparent 70%);
}

/* ---------- Kaart ---------- */
.pxui-auth-card {
  position: relative; z-index: 1;
  width: 100%; max-width: 400px;
  display: flex; flex-direction: column;
}
.pxui-auth-centered .pxui-auth-card {
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--r-xl); box-shadow: var(--sh-lg);
  padding: 32px;
}
.pxui-auth-brand { display: flex; align-items: center; gap: 11px; margin-bottom: 26px; }
.pxui-auth-title { font-size: 26px; font-weight: 700; letter-spacing: -0.03em; color: var(--text); }
.pxui-auth-description { margin-top: 8px; font-size: 14.5px; color: var(--text-2); line-height: 1.55; }
.pxui-auth-body { display: flex; flex-direction: column; gap: 14px; margin-top: 24px; }
.pxui-auth-footer {
  margin-top: 22px; padding-top: 18px; border-top: 1px solid var(--border);
  font-size: 13.5px; color: var(--text-3); text-align: center;
}

/* ---------- Scheiding ---------- */
.pxui-auth-divider {
  display: flex; align-items: center; gap: 12px;
  color: var(--text-3); font-size: 12.5px; font-weight: 600;
}
.pxui-auth-divider::before,
.pxui-auth-divider::after {
  content: ""; flex: 1; height: 1px; background: var(--border);
}

/* ---------- SSO-knop ---------- */
.pxui-sso {
  --pxui-sso-color: var(--accent);
  display: flex; align-items: center; gap: 13px; width: 100%;
  padding: calc(12px * var(--density)) 15px;
  background: var(--surface); border: 1px solid var(--border-strong);
  border-radius: var(--r-md); cursor: pointer; text-align: left;
  font: inherit; color: var(--text);
  transition: border-color var(--dur-fast), background var(--dur-fast), box-shadow var(--dur-fast);
}
.pxui-sso:hover:not(:disabled) {
  border-color: var(--pxui-sso-color); background: var(--surface-hover); box-shadow: var(--sh-xs);
}
.pxui-sso:focus-visible { outline: none; box-shadow: var(--ring); }
.pxui-sso:disabled { opacity: .6; cursor: not-allowed; }

.pxui-sso-icon {
  display: grid; place-items: center; flex: none;
  width: 36px; height: 36px; border-radius: var(--r-sm);
  background: color-mix(in srgb, var(--pxui-sso-color) 14%, transparent);
  color: var(--pxui-sso-color);
}
.pxui-sso-icon svg { width: 19px; height: 19px; }
.pxui-sso-spin { animation: pxui-spin 1s linear infinite; }

.pxui-sso-text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.pxui-sso-label { font-size: 14px; font-weight: 650; color: var(--text); }
.pxui-sso-description { font-size: 12px; color: var(--text-3); }
.pxui-sso-arrow { flex: none; color: var(--text-3); transition: transform var(--dur-fast); }
.pxui-sso:hover:not(:disabled) .pxui-sso-arrow { transform: translateX(2px); color: var(--pxui-sso-color); }

@media (max-width: 900px) {
  .pxui-auth-split { grid-template-columns: 1fr; }
  .pxui-auth-aside { display: none; }
}

@media (max-width: 520px) {
  .pxui-auth-main { padding: 26px 18px; }
  .pxui-auth-centered .pxui-auth-card { padding: 24px 20px; }
  .pxui-auth-title { font-size: 22px; }
}
